<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, messageOf } from '../api'

interface Child { id:number; child_code:string; nickname:string; birth_month:string|null }
interface Activity { id:number; activity_code:string; name:string; category:string; age_min_months:number; age_max_months:number; objective:string; materials:string[]; steps:string[]; suggested_duration_minutes:number; precautions:string; is_active:boolean; is_builtin:boolean }
interface RecordItem { id:number; child_id:number; child_code:string; child_nickname:string; activity_id:number; activity_code:string; activity_name:string; activity_category:string; activity_objective:string; suggested_duration_minutes:number; activity_date:string; completion_status:string; completion_label:string; actual_duration_minutes:number|null; child_response:string|null; notes:string|null; activity_is_active:boolean; created_at:string; updated_at:string; disclaimer:string }

const route=useRoute(); const router=useRouter(); const tab=ref('library'); const disclaimer=ref(''); const categories=ref<string[]>([]); const children=ref<Child[]>([])
const activities=ref<Activity[]>([]); const allActivities=ref<Activity[]>([]); const activityTotal=ref(0); const activityPage=ref(1); const activityLoading=ref(false); const search=ref(''); const category=ref(''); const ageChild=ref<number|null>(null); const ageMessage=ref('')
const records=ref<RecordItem[]>([]); const recordTotal=ref(0); const recordPage=ref(1); const recordPageSize=ref(10); const recordLoading=ref(false); const recordChild=ref<number|null>(null); const recordCategory=ref(''); const recordDates=ref<[string,string]|null>(null)
const stats=ref<any>({total_records:0,month_records:0,completed_records:0,partial_records:0,not_completed_records:0,latest_activity_date:null,category_counts:{}})
const detailOpen=ref(false); const activityDetail=ref<Activity|null>(null); const recordDetail=ref<RecordItem|null>(null); const recordDetailOpen=ref(false)
const recordDialog=ref(false); const recordSubmitting=ref(false); const editingRecord=ref<number|null>(null)
const recordForm=reactive({child_id:null as number|null,activity_id:null as number|null,activity_date:'',completion_status:'',actual_duration_minutes:null as number|null,child_response:'',notes:''})
const manageDialog=ref(false); const manageSubmitting=ref(false); const editingActivity=ref<number|null>(null)
const activityForm=reactive({activity_code:'',name:'',category:'',age_min_months:24,age_max_months:120,objective:'',materials_text:'',steps_text:'',suggested_duration_minutes:10,precautions:''})
const completionOptions=[['COMPLETED','已完成'],['PARTIAL','部分完成'],['NOT_COMPLETED','未完成']]

function today(){const now=new Date();return new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function ageText(activity:Activity){const format=(m:number)=>m%12?`${Math.floor(m/12)}岁${m%12}个月`:`${m/12}岁`;return `${format(activity.age_min_months)}–${format(activity.age_max_months)}`}
function formatDate(value:string|null){return value?new Date(value).toLocaleDateString('zh-CN'):'暂无'}
async function loadChildren(){children.value=(await api.get('/children',{params:{page_size:100}})).data.items}
async function loadActivities(manage=false){
  activityLoading.value=true
  try{const {data}=await api.get('/activities',{params:{q:manage?'':search.value.trim(),category:manage?undefined:category.value||undefined,child_id:manage?undefined:ageChild.value||undefined,active_only:!manage,page:manage?1:activityPage.value,page_size:manage?100:12}}); if(manage)allActivities.value=data.items;else{activities.value=data.items;activityTotal.value=data.total;categories.value=data.categories;disclaimer.value=data.disclaimer;ageMessage.value=data.age_filter?.message||''}}
  catch(reason){ElMessage.error(messageOf(reason))}finally{activityLoading.value=false}
}
async function loadRecords(){recordLoading.value=true;try{const {data}=await api.get('/activity-records',{params:{child_id:recordChild.value||undefined,category:recordCategory.value||undefined,date_from:recordDates.value?.[0],date_to:recordDates.value?.[1],page:recordPage.value,page_size:recordPageSize.value}});records.value=data.items;recordTotal.value=data.total}catch(reason){ElMessage.error(messageOf(reason))}finally{recordLoading.value=false}}
async function loadStats(){try{stats.value=(await api.get('/activity-records/stats',{params:{child_id:recordChild.value||undefined}})).data}catch(reason){ElMessage.error(messageOf(reason))}}
function refreshActivities(){activityPage.value=1;void loadActivities()}
function refreshRecords(){recordPage.value=1;void Promise.all([loadRecords(),loadStats()])}
async function showActivity(activity:Activity){try{activityDetail.value=(await api.get(`/activities/${activity.id}`)).data;detailOpen.value=true}catch(reason){ElMessage.error(messageOf(reason))}}
function resetRecord(){Object.assign(recordForm,{child_id:recordChild.value,activity_id:null,activity_date:today(),completion_status:'',actual_duration_minutes:null,child_response:'',notes:''})}
function createRecord(activity:Activity|null=null){editingRecord.value=null;resetRecord();if(activity)recordForm.activity_id=activity.id;recordDialog.value=true}
async function editRecord(row:RecordItem){try{const {data}=await api.get(`/activity-records/${row.id}`);editingRecord.value=row.id;Object.assign(recordForm,{child_id:data.child_id,activity_id:data.activity_id,activity_date:data.activity_date,completion_status:data.completion_status,actual_duration_minutes:data.actual_duration_minutes,child_response:data.child_response||'',notes:data.notes||''});recordDialog.value=true}catch(reason){ElMessage.error(messageOf(reason))}}
async function saveRecord(){
  if(!recordForm.child_id||!recordForm.activity_id||!recordForm.activity_date||!recordForm.completion_status)return ElMessage.warning('请完整选择儿童、活动、日期和完成情况')
  recordSubmitting.value=true;const payload={...recordForm,child_response:recordForm.child_response.trim()||null,notes:recordForm.notes.trim()||null}
  try{if(editingRecord.value)await api.put(`/activity-records/${editingRecord.value}`,payload);else await api.post('/activity-records',payload);ElMessage.success(editingRecord.value?'活动记录已更新':'活动记录已保存');recordDialog.value=false;tab.value='records';await Promise.all([loadRecords(),loadStats()])}catch(reason){ElMessage.error(messageOf(reason))}finally{recordSubmitting.value=false}
}
async function showRecord(row:RecordItem){try{recordDetail.value=(await api.get(`/activity-records/${row.id}`)).data;recordDetailOpen.value=true}catch(reason){ElMessage.error(messageOf(reason))}}
async function removeRecord(row:RecordItem){try{await ElMessageBox.confirm(`确认删除“${row.activity_name}”的本次记录吗？`,'删除活动记录',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});await api.delete(`/activity-records/${row.id}`);ElMessage.success('活动记录已删除');await Promise.all([loadRecords(),loadStats()])}catch(reason:any){if(reason!=='cancel'&&reason!=='close')ElMessage.error(messageOf(reason))}}
function resetActivity(){Object.assign(activityForm,{activity_code:'',name:'',category:'',age_min_months:24,age_max_months:120,objective:'',materials_text:'',steps_text:'',suggested_duration_minutes:10,precautions:''})}
function createActivity(){editingActivity.value=null;resetActivity();manageDialog.value=true}
function editActivity(item:Activity){editingActivity.value=item.id;Object.assign(activityForm,{activity_code:item.activity_code,name:item.name,category:item.category,age_min_months:item.age_min_months,age_max_months:item.age_max_months,objective:item.objective,materials_text:item.materials.join('\n'),steps_text:item.steps.join('\n'),suggested_duration_minutes:item.suggested_duration_minutes,precautions:item.precautions});manageDialog.value=true}
async function saveActivity(){
  if(!activityForm.name.trim()||!activityForm.category||!activityForm.objective.trim()||!activityForm.materials_text.trim()||!activityForm.steps_text.trim()||!activityForm.precautions.trim())return ElMessage.warning('请填写完整活动信息')
  manageSubmitting.value=true;const payload={name:activityForm.name,category:activityForm.category,age_min_months:activityForm.age_min_months,age_max_months:activityForm.age_max_months,objective:activityForm.objective,materials:activityForm.materials_text.split('\n').map(v=>v.trim()).filter(Boolean),steps:activityForm.steps_text.split('\n').map(v=>v.trim()).filter(Boolean),suggested_duration_minutes:activityForm.suggested_duration_minutes,precautions:activityForm.precautions,...(!editingActivity.value&&activityForm.activity_code?{activity_code:activityForm.activity_code}: {})}
  try{if(editingActivity.value)await api.put(`/activities/${editingActivity.value}`,payload);else await api.post('/activities',payload);ElMessage.success(editingActivity.value?'活动已更新':'活动已新增');manageDialog.value=false;await Promise.all([loadActivities(true),loadActivities()])}catch(reason){ElMessage.error(messageOf(reason))}finally{manageSubmitting.value=false}
}
async function toggleActivity(item:Activity){try{await api.patch(`/activities/${item.id}/status`,{is_active:!item.is_active});ElMessage.success(item.is_active?'活动已停用，历史记录仍保留':'活动已启用');await Promise.all([loadActivities(true),loadActivities()])}catch(reason){ElMessage.error(messageOf(reason))}}
function goObservations(){void router.push({path:'/observations',query:recordChild.value?{child:String(recordChild.value)}:{}})}
function handleTabChange(value:string|number){if(value==='records')refreshRecords();if(value==='manage')void loadActivities(true)}

onMounted(async()=>{try{await loadChildren();const child=Number(route.query.child);if(Number.isInteger(child)&&child>0){recordChild.value=child;tab.value='records'}await Promise.all([loadActivities(),loadActivities(true),loadRecords(),loadStats()]);const recordId=Number(route.query.record);if(Number.isInteger(recordId)&&recordId>0){tab.value='records';await showRecord({id:recordId} as RecordItem)}}catch(reason){ElMessage.error(messageOf(reason))}})
</script>

<template>
  <div class="page-head"><h1>家庭互动活动</h1><el-button @click="goObservations">查看行为观察</el-button></div>
  <el-alert v-if="disclaimer" :title="disclaimer" type="warning" show-icon :closable="false" class="notice"/>
  <el-tabs v-model="tab" class="activity-tabs" @tab-change="handleTabChange">
    <el-tab-pane label="活动资源库" name="library">
      <section class="panel"><div class="toolbar"><el-input v-model="search" clearable placeholder="搜索活动名称或编号" @keyup.enter="refreshActivities" @clear="refreshActivities"/><el-select v-model="category" clearable placeholder="全部分类" @change="refreshActivities"><el-option v-for="item in categories" :key="item" :value="item"/></el-select><el-select v-model="ageChild" clearable filterable placeholder="按儿童年龄参考筛选" @change="refreshActivities"><el-option v-for="child in children" :key="child.id" :value="child.id" :label="`${child.child_code} · ${child.nickname}`"/></el-select><el-button @click="refreshActivities">查询</el-button></div><el-alert v-if="ageMessage" :title="ageMessage" type="info" :closable="false" class="age-tip"/><div v-loading="activityLoading" class="activity-grid"><article v-for="item in activities" :key="item.id"><div><el-tag effect="plain">{{ item.category }}</el-tag><small>{{ item.activity_code }}</small></div><h3>{{ item.name }}</h3><p>{{ item.objective }}</p><dl><dt>参考年龄</dt><dd>{{ ageText(item) }}</dd><dt>建议时长</dt><dd>{{ item.suggested_duration_minutes }} 分钟</dd></dl><footer><el-button @click="showActivity(item)">查看详情</el-button><el-button type="primary" @click="createRecord(item)">记录活动</el-button></footer></article><div v-if="!activities.length" class="empty">没有符合条件的活动</div></div><div class="pagination"><span>共 {{ activityTotal }} 项</span><el-pagination v-model:current-page="activityPage" layout="prev,pager,next" :page-size="12" :total="activityTotal" @current-change="loadActivities()"/></div></section>
    </el-tab-pane>
    <el-tab-pane label="活动记录" name="records">
      <div class="stats"><article><span>记录总数</span><b>{{ stats.total_records }}</b></article><article><span>本月记录</span><b>{{ stats.month_records }}</b></article><article><span>已完成</span><b>{{ stats.completed_records }}</b></article><article><span>最近活动</span><b class="date-value">{{ stats.latest_activity_date||'暂无' }}</b></article></div>
      <section class="panel"><div class="record-head"><div class="toolbar"><el-select v-model="recordChild" clearable filterable placeholder="全部儿童" @change="refreshRecords"><el-option v-for="child in children" :key="child.id" :value="child.id" :label="`${child.child_code} · ${child.nickname}`"/></el-select><el-select v-model="recordCategory" clearable placeholder="全部分类" @change="refreshRecords"><el-option v-for="item in categories" :key="item" :value="item"/></el-select><el-date-picker v-model="recordDates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至" @change="refreshRecords"/></div><el-button type="primary" @click="createRecord()">新建活动记录</el-button></div><div v-if="Object.keys(stats.category_counts).length" class="category-counts"><span v-for="(count,key) in stats.category_counts" :key="key">{{ key }} {{ count }} 次</span></div><el-table v-loading="recordLoading" :data="records" stripe><el-table-column label="儿童档案" min-width="180"><template #default="scope"><b>{{ scope.row.child_code }}</b><small>{{ scope.row.child_nickname }}</small></template></el-table-column><el-table-column prop="activity_name" label="活动" min-width="170"><template #default="scope">{{ scope.row.activity_name }}<small>{{ scope.row.activity_category }}</small></template></el-table-column><el-table-column prop="activity_date" label="日期" width="115"/><el-table-column label="完成情况" width="110"><template #default="scope"><el-tag :type="scope.row.completion_status==='COMPLETED'?'success':scope.row.completion_status==='PARTIAL'?'warning':'info'">{{ scope.row.completion_label }}</el-tag></template></el-table-column><el-table-column label="实际时长" width="105"><template #default="scope">{{ scope.row.actual_duration_minutes==null?'未填写':`${scope.row.actual_duration_minutes} 分钟` }}</template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="scope"><el-button link type="primary" @click="showRecord(scope.row)">查看</el-button><el-button link @click="editRecord(scope.row)">编辑</el-button><el-button link type="danger" @click="removeRecord(scope.row)">删除</el-button></template></el-table-column><template #empty><div class="empty"><span>暂无活动记录</span><el-button link type="primary" @click="createRecord()">记录第一次活动</el-button></div></template></el-table><div class="pagination"><span>共 {{ recordTotal }} 条</span><el-pagination v-model:current-page="recordPage" v-model:page-size="recordPageSize" layout="prev,pager,next,sizes" :page-sizes="[10,20,50]" :total="recordTotal" @current-change="loadRecords" @size-change="refreshRecords"/></div></section>
    </el-tab-pane>
    <el-tab-pane label="活动管理" name="manage">
      <section class="panel"><div class="manage-head"><h2>活动管理</h2><el-button type="primary" @click="createActivity">新增活动</el-button></div><el-table :data="allActivities" stripe><el-table-column prop="activity_code" label="编号" width="145"/><el-table-column prop="name" label="名称" min-width="160"/><el-table-column prop="category" label="分类" width="160"/><el-table-column label="来源" width="90"><template #default="scope">{{ scope.row.is_builtin?'系统内置':'管理员新增' }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="scope"><el-tag :type="scope.row.is_active?'success':'info'">{{ scope.row.is_active?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="scope"><el-button link @click="editActivity(scope.row)">编辑</el-button><el-button link :type="scope.row.is_active?'danger':'primary'" @click="toggleActivity(scope.row)">{{ scope.row.is_active?'停用':'启用' }}</el-button></template></el-table-column></el-table></section>
    </el-tab-pane>
  </el-tabs>

  <el-drawer v-model="detailOpen" title="活动详情" size="min(650px,94vw)"><template v-if="activityDetail"><div class="drawer-title"><el-tag>{{ activityDetail.category }}</el-tag><h2>{{ activityDetail.name }}</h2><span>{{ ageText(activityDetail) }} · 建议 {{ activityDetail.suggested_duration_minutes }} 分钟</span></div><h3>活动目标</h3><p>{{ activityDetail.objective }}</p><h3>所需材料</h3><ul><li v-for="item in activityDetail.materials" :key="item">{{ item }}</li></ul><h3>操作步骤</h3><ol><li v-for="step in activityDetail.steps" :key="step">{{ step }}</li></ol><h3>注意事项</h3><el-alert :title="activityDetail.precautions" type="warning" :closable="false"/><el-button type="primary" size="large" class="drawer-action" @click="detailOpen=false;createRecord(activityDetail)">记录本次活动</el-button></template></el-drawer>

  <el-dialog v-model="recordDialog" :title="editingRecord?'编辑活动记录':'新建活动记录'" width="650px"><div class="form-grid"><label>儿童档案<el-select v-model="recordForm.child_id" filterable placeholder="请选择"><el-option v-for="child in children" :key="child.id" :value="child.id" :label="`${child.child_code} · ${child.nickname}`"/></el-select></label><label>互动活动<el-select v-model="recordForm.activity_id" filterable placeholder="请选择"><el-option v-for="item in allActivities.filter(v=>v.is_active||v.id===recordForm.activity_id)" :key="item.id" :value="item.id" :label="`${item.name} · ${item.category}${item.is_active?'':'（已停用）'}`"/></el-select></label><label>活动日期<el-date-picker v-model="recordForm.activity_date" type="date" value-format="YYYY-MM-DD" :disabled-date="(d:Date)=>d.getTime()>Date.now()" style="width:100%"/></label><label>完成情况<el-select v-model="recordForm.completion_status" placeholder="请选择"><el-option v-for="item in completionOptions" :key="item[0]" :value="item[0]" :label="item[1]"/></el-select></label><label>实际时长（分钟，可选）<el-input-number v-model="recordForm.actual_duration_minutes" :min="0" :max="480" controls-position="right" style="width:100%"/></label></div><label class="wide-field">儿童参与反馈<el-input v-model="recordForm.child_response" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="记录实际参与过程，不作疾病或疗效推断"/></label><label class="wide-field">其他备注<el-input v-model="recordForm.notes" type="textarea" :rows="3" maxlength="4000" show-word-limit/></label><el-alert title="未完成只表示本次活动未完成，不代表儿童能力不足或行为异常。" type="info" :closable="false"/><template #footer><el-button @click="recordDialog=false">取消</el-button><el-button type="primary" :loading="recordSubmitting" @click="saveRecord">保存记录</el-button></template></el-dialog>

  <el-drawer v-model="recordDetailOpen" title="活动记录详情" size="min(620px,94vw)"><template v-if="recordDetail"><el-alert :title="recordDetail.disclaimer" type="warning" :closable="false"/><el-descriptions :column="1" border class="record-descriptions"><el-descriptions-item label="儿童档案">{{ recordDetail.child_code }} · {{ recordDetail.child_nickname }}</el-descriptions-item><el-descriptions-item label="活动">{{ recordDetail.activity_name }}（{{ recordDetail.activity_code }}）</el-descriptions-item><el-descriptions-item label="活动分类">{{ recordDetail.activity_category }}</el-descriptions-item><el-descriptions-item label="活动日期">{{ recordDetail.activity_date }}</el-descriptions-item><el-descriptions-item label="完成情况">{{ recordDetail.completion_label }}</el-descriptions-item><el-descriptions-item label="实际时长">{{ recordDetail.actual_duration_minutes==null?'未填写':`${recordDetail.actual_duration_minutes} 分钟` }}</el-descriptions-item></el-descriptions><h3>活动目标快照</h3><p>{{ recordDetail.activity_objective }}</p><h3>儿童参与反馈</h3><p class="text-box">{{ recordDetail.child_response||'未填写' }}</p><h3>其他备注</h3><p class="text-box">{{ recordDetail.notes||'未填写' }}</p></template></el-drawer>

  <el-dialog v-model="manageDialog" :title="editingActivity?'编辑活动资源':'新增活动资源'" width="720px"><div class="form-grid"><label v-if="!editingActivity">活动编号（可选）<el-input v-model="activityForm.activity_code" placeholder="留空由系统生成"/></label><label>活动名称<el-input v-model="activityForm.name" maxlength="100"/></label><label>活动分类<el-select v-model="activityForm.category"><el-option v-for="item in categories" :key="item" :value="item"/></el-select></label><label>最小月龄<el-input-number v-model="activityForm.age_min_months" :min="0" :max="216"/></label><label>最大月龄<el-input-number v-model="activityForm.age_max_months" :min="0" :max="216"/></label><label>建议时长（分钟）<el-input-number v-model="activityForm.suggested_duration_minutes" :min="1" :max="180"/></label></div><label class="wide-field">活动目标<el-input v-model="activityForm.objective" type="textarea" :rows="2" maxlength="2000"/></label><label class="wide-field">所需材料（每行一项）<el-input v-model="activityForm.materials_text" type="textarea" :rows="3"/></label><label class="wide-field">操作步骤（每行一步）<el-input v-model="activityForm.steps_text" type="textarea" :rows="5"/></label><label class="wide-field">注意事项<el-input v-model="activityForm.precautions" type="textarea" :rows="3" maxlength="2000"/></label><template #footer><el-button @click="manageDialog=false">取消</el-button><el-button type="primary" :loading="manageSubmitting" @click="saveActivity">保存活动</el-button></template></el-dialog>
</template>

<style scoped>
.notice{margin-bottom:16px}.activity-tabs :deep(.el-tabs__header){margin-bottom:16px}.toolbar{display:flex;gap:10px;flex-wrap:wrap}.toolbar .el-input,.toolbar .el-select{width:210px}.age-tip{margin-top:12px}.activity-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:16px;min-height:120px}.activity-grid article{border:1px solid #e2e9eb;border-radius:10px;padding:16px;display:flex;flex-direction:column}.activity-grid article>div{display:flex;justify-content:space-between;align-items:center}.activity-grid small{color:#8a989d}.activity-grid h3{font-size:17px;margin:14px 0 8px}.activity-grid p{color:#5e7177;font-size:13px;line-height:1.7;flex:1}.activity-grid dl{display:grid;grid-template-columns:70px 1fr;gap:6px;font-size:12px}.activity-grid dt{color:#839196}.activity-grid dd{margin:0}.activity-grid footer{display:flex;gap:8px;margin-top:14px}.empty{grid-column:1/-1;padding:36px;text-align:center;color:#89989d;display:flex;flex-direction:column;gap:8px}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:18px;color:#7b898f;font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.stats article{background:white;border:1px solid #e3eaec;border-radius:9px;padding:14px}.stats span,.stats b{display:block}.stats span{font-size:12px;color:#77898e}.stats b{font-size:24px;color:#286a6e;margin-top:8px}.stats .date-value{font-size:16px}.record-head,.manage-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.manage-head p{color:#728489}.category-counts{display:flex;gap:8px;flex-wrap:wrap;margin:13px 0}.category-counts span{background:#edf5f4;color:#426e70;border-radius:16px;padding:5px 10px;font-size:12px}.el-table small{display:block;color:#89979c;margin-top:4px}.drawer-title{margin-bottom:22px}.drawer-title h2{margin:12px 0 6px}.drawer-title span{font-size:13px;color:#72848a}.el-drawer p,.el-drawer li{line-height:1.8;color:#52676d}.drawer-action